set +e; printf '__ZCODE_PROBE_PLATFORM__\n'; uname -s; printf '__ZCODE_PROBE_ARCH__\n'; uname -m; printf '__ZCODE_PROBE_ROOT__\n'; printf '%s\n' "$HOME/.zcode/server"; printf '__ZCODE_PROBE_KERNEL__\n'; if [ -r /proc/sys/kernel/ostype ]; then cat /proc/sys/kernel/ostype; else printf '\n'; fi; printf '__ZCODE_PROBE_LIBC__\n'; getconf GNU_LIBC_VERSION 2>/dev/null; printf '__ZCODE_PROBE_INSTALLED__\n'; if [ -f "$HOME/.zcode/server/bin/zcode" ]; then printf '1\n'; else printf '0\n'; fi; printf '__ZCODE_PROBE_VERSION__\n'; if [ -r "$HOME/.zcode/server"/current.json ]; then sed -n 's/^[[:space:]]*"version"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$HOME/.zcode/server"/current.json | head -n 1; fi; printf '__ZCODE_PROBE_STATUS__\n'; if [ -r "$HOME/.zcode/server"/run/status.json ]; then status_pid=$(sed -n 's/^[[:space:]]*"pid"[[:space:]]*:[[:space:]]*\([0-9][0-9]*\).*/\1/p' "$HOME/.zcode/server"/run/status.json | head -n 1); if [ -n "$status_pid" ] && kill -0 "$status_pid" 2>/dev/null; then tr -d '\r\n' < "$HOME/.zcode/server"/run/status.json; printf '\n'; fi; fi; printf '__ZCODE_PROBE_END__\n'
